export const MARS_RADIUS=3396190;
export const M_PER_DEG=Math.PI*MARS_RADIUS/180;
export function buildTerrain(raw){
 const {width:w,height:h,bounds:b}=raw,e=Float64Array.from(raw.elevation,v=>v===null?NaN:v),n=w*h;
 const lonStep=(b[2]-b[0])/w,latStep=(b[3]-b[1])/h,dx=lonStep*M_PER_DEG*Math.cos((b[1]+b[3])/2*Math.PI/180),dy=latStep*M_PER_DEG;
 const slope=new Float64Array(n),rough=new Float64Array(n),valid=new Uint8Array(n);slope.fill(NaN);rough.fill(NaN);
 for(let r=0;r<h;r++)for(let c=0;c<w;c++){const i=r*w+c;let sum=0,sq=0,count=0,nearMissing=false;for(let dr=-1;dr<=1;dr++)for(let dc=-1;dc<=1;dc++){const rr=r+dr,cc=c+dc;if(rr<0||rr>=h||cc<0||cc>=w)continue;const z=e[rr*w+cc];if(!Number.isFinite(z)){nearMissing=true;continue}sum+=z;sq+=z*z;count++}if(!Number.isFinite(e[i])||nearMissing||count<3)continue;const c0=Math.max(0,c-1),c1=Math.min(w-1,c+1),r0=Math.max(0,r-1),r1=Math.min(h-1,r+1);const dzdx=(e[r*w+c1]-e[r*w+c0])/((c1-c0)*dx),dzdy=(e[r1*w+c]-e[r0*w+c])/((r1-r0)*dy);slope[i]=Math.atan(Math.hypot(dzdx,dzdy))*180/Math.PI;rough[i]=Math.min(1,Math.sqrt(Math.max(0,sq/count-(sum/count)**2))/25);valid[i]=1;}
 return{raw,w,h,n,b,e,slope,rough,valid,dx,dy,lonStep,latStep};
}
export function toIndex(t,p){const{w,h,b,lonStep,latStep}=t;if(!Number.isFinite(p.lon)||!Number.isFinite(p.lat)||p.lon<b[0]||p.lon>b[2]||p.lat<b[1]||p.lat>b[3])throw new Error(`Coordinates must be within ${b[0].toFixed(3)}–${b[2].toFixed(3)}°E, ${b[1].toFixed(3)}–${b[3].toFixed(3)}°N.`);const c=Math.max(0,Math.min(w-1,Math.floor((p.lon-b[0])/lonStep))),r=Math.max(0,Math.min(h-1,Math.floor((b[3]-p.lat)/latStep)));return r*w+c;}
export function toCoordinate(t,i){const r=Math.floor(i/t.w),c=i%t.w;return[t.b[0]+(c+.5)*t.lonStep,t.b[3]-(r+.5)*t.latStep,Number.isFinite(t.e[i])?t.e[i]:null];}
export function project(lon,lat){return[(lon-77.575)*M_PER_DEG*Math.cos(18.4*Math.PI/180),(lat-18.4)*M_PER_DEG];}
export function unproject(x,y){return{lon:x/(M_PER_DEG*Math.cos(18.4*Math.PI/180))+77.575,lat:y/M_PER_DEG+18.4};}
export function extentFor(b){return[...project(b[0],b[1]),...project(b[2],b[3])];}
export function rasterImage(t,kind,maxSlope=20,maxRough=.85){const canvas=document.createElement('canvas');canvas.width=t.w;canvas.height=t.h;const cx=canvas.getContext('2d'),image=cx.createImageData(t.w,t.h);let min=Infinity,max=-Infinity;for(const z of t.e)if(Number.isFinite(z)){min=Math.min(min,z);max=Math.max(max,z)}for(let i=0;i<t.n;i++){const z=t.e[i],s=t.slope[i],rough=t.rough[i],j=i*4,r=Math.floor(i/t.w),c=i%t.w;let rgb=[0,0,0],a=255;if(kind==='hazards'){if(!t.valid[i]){rgb=[148,151,156];a=35}else if(s>maxSlope||rough>maxRough){rgb=[193,101,85];a=104}else{const stress=Math.max(s/Math.max(maxSlope,1),rough/Math.max(maxRough,.1));if(stress>.45){rgb=[195,152,82];a=Math.round(12+Math.min(1,(stress-.45)/.55)*70)}else a=0}}else if(kind==='slope'){if(!t.valid[i]||!Number.isFinite(s)){a=0}else{const u=Math.min(1,Math.max(0,s/Math.max(maxSlope*1.25,25)));rgb=[Math.round(40+215*u),Math.round(190-135*u),Math.round(130-100*u)];a=Math.round(45+135*u)}}else if(kind==='roughness'){if(!t.valid[i]||!Number.isFinite(rough)){a=0}else{const u=Math.min(1,Math.max(0,rough/Math.max(maxRough,0.5)));rgb=[Math.round(90+155*u),Math.round(135-65*u),Math.round(220-30*u)];a=Math.round(40+140*u)}}else if(kind==='coverage'){rgb=t.valid[i]?[92,190,153]:[165,169,176];a=t.valid[i]?38:130;}else if(kind==='hillshade'){if(!t.valid[i])a=0;else{const cl=Math.max(0,c-1),cr=Math.min(t.w-1,c+1),rt=Math.max(0,r-1),rb=Math.min(t.h-1,r+1),gx=(t.e[r*t.w+cr]-t.e[r*t.w+cl])/Math.max(t.dx*(cr-cl),1),gy=(t.e[rb*t.w+c]-t.e[rt*t.w+c])/Math.max(t.dy*(rb-rt),1),norm=Math.hypot(gx,gy,1),illum=Math.max(0,(-gx*-.5-gy*-.5+.707)/norm);rgb=[0,0,0];a=Math.round((1-illum)*145)}}else{if(!Number.isFinite(z)){rgb=[43,45,48];a=0}else{const u=(z-min)/(max-min||1),shade=.75+.25*Math.cos((s||0)/18),stops=[[35,40,40],[66,68,62],[111,104,88],[160,143,117],[204,185,149]],p=Math.min(3.999,u*4),k=Math.floor(p),f=p-k;rgb=stops[k].map((v,j)=>Math.round((v*(1-f)+stops[k+1][j]*f)*shade))}}if(kind==='context'){const gray=Math.round(rgb[0]*.299+rgb[1]*.587+rgb[2]*.114);rgb=[gray,gray,gray]}image.data.set([...rgb,a],j)}cx.putImageData(image,0,0);if(kind==='hazards'){const soft=document.createElement('canvas');soft.width=t.w*3;soft.height=t.h*3;const sc=soft.getContext('2d');sc.imageSmoothingEnabled=true;sc.filter='blur(1px)';sc.drawImage(canvas,0,0,soft.width,soft.height);return soft.toDataURL('image/png')}return canvas.toDataURL('image/png');}
